import type { Order } from './order.service.js';
import { lookupOrder, ORDERS } from './order.service.js';
import { err, ok, type Result } from '../kernel/result.js';

export function refundOrder(orderId: string): Result<Order, string> {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return err(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    return err(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    return err(
      `Order ${orderId} has total ${order.total}, which is less than the minimum 10`,
    );
  }

  const index = ORDERS.indexOf(order);
  const refundedOrder = { ...order, refunded: true };
  ORDERS[index] = refundedOrder;
  return ok(refundedOrder);
}

